package com.fooddelivery;

import com.fooddelivery.config.EmbeddedKafkaConfig;
import com.fooddelivery.config.EmbeddedKafkaHolder;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class FoodDeliveryOrderTrackingApplication {

    public static void main(String[] args) {
        // Boot the in-process Kafka broker BEFORE Spring starts so that the
        // dynamically-allocated bootstrap servers are available to Spring
        // Boot's Kafka auto-configuration via system property.
        EmbeddedKafkaHolder.start(EmbeddedKafkaConfig.TOPIC, 3);

        SpringApplication.run(FoodDeliveryOrderTrackingApplication.class, args);
    }
}

package com.fooddelivery;

import java.time.Instant;

public class OrderEvent {
    private String orderId;
    private OrderState state;
    private Instant timestamp;

    public OrderEvent() {}

    public OrderEvent(String orderId, OrderState state, Instant timestamp) {
        this.orderId = orderId;
        this.state = state;
        this.timestamp = timestamp;
    }

    public String getOrderId() { return orderId; }
    public void setOrderId(String orderId) { this.orderId = orderId; }

    public OrderState getState() { return state; }
    public void setState(OrderState state) { this.state = state; }

    public Instant getTimestamp() { return timestamp; }
    public void setTimestamp(Instant timestamp) { this.timestamp = timestamp; }
}

package com.fooddelivery;

import java.time.Instant;

/**
 * Domain event published every time an order transitions from one state to
 * another in the lifecycle:
 *
 *   PLACED -> ACCEPTED -> PREPARING -> OUT_FOR_DELIVERY -> DELIVERED
 */
public class OrderEvent {

    private String orderId;
    private OrderState previousState;
    private OrderState state;
    private Instant timestamp;

    public OrderEvent() {}

    public OrderEvent(String orderId, OrderState previousState, OrderState state, Instant timestamp) {
        this.orderId = orderId;
        this.previousState = previousState;
        this.state = state;
        this.timestamp = timestamp;
    }

    public String getOrderId() { return orderId; }
    public void setOrderId(String orderId) { this.orderId = orderId; }

    public OrderState getPreviousState() { return previousState; }
    public void setPreviousState(OrderState previousState) { this.previousState = previousState; }

    public OrderState getState() { return state; }
    public void setState(OrderState state) { this.state = state; }

    public Instant getTimestamp() { return timestamp; }
    public void setTimestamp(Instant timestamp) { this.timestamp = timestamp; }

    @Override
    public String toString() {
        return "OrderEvent{" +
                "orderId='" + orderId + '\'' +
                ", previousState=" + previousState +
                ", state=" + state +
                ", timestamp=" + timestamp +
                '}';
    }
}

package com.fooddelivery.config;

import org.springframework.kafka.test.EmbeddedKafkaBroker;
import org.springframework.kafka.test.EmbeddedKafkaZKBroker;

/**
 * Static holder that owns the lifecycle of the in-process Kafka broker.
 * It is started from {@code main()} before Spring boots so the broker's
 * bootstrap-servers are already available when the Spring auto-configuration
 * for Kafka kicks in.
 */
public final class EmbeddedKafkaHolder {

    private static volatile EmbeddedKafkaBroker BROKER;

    private EmbeddedKafkaHolder() {
        // utility class
    }

    public static synchronized EmbeddedKafkaBroker start(String topic, int partitions) {
        if (BROKER != null) {
            return BROKER;
        }
        EmbeddedKafkaBroker broker = new EmbeddedKafkaZKBroker(1, true, partitions, topic)
                .brokerProperty("listeners", "PLAINTEXT://localhost:0")
                .brokerProperty("port", "0");
        broker.afterPropertiesSet();

        // Make Spring Boot Kafka auto-config pick this up.
        System.setProperty("spring.kafka.bootstrap-servers", broker.getBrokersAsString());

        BROKER = broker;
        return broker;
    }

    public static EmbeddedKafkaBroker getBroker() {
        return BROKER;
    }
}

