    }
}

package com.fooddelivery.producer;

import com.fooddelivery.OrderEvent;
import com.fooddelivery.OrderState;
import org.apache.kafka.clients.producer.RecordMetadata;
import org.apache.kafka.common.TopicPartition;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.SendResult;

import java.util.concurrent.CompletableFuture;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for {@link OrderService}. Generated by the agentic-AI demo.
 */
class OrderServiceTest {

    @SuppressWarnings("unchecked")
    private final KafkaTemplate<String, OrderEvent> kafka = mock(KafkaTemplate.class);
    private OrderService service;

    @BeforeEach
    void setUp() {
        // Default: send returns a completed future with synthetic metadata.
        SendResult<String, OrderEvent> result = mock(SendResult.class);
        RecordMetadata md = new RecordMetadata(new TopicPartition("order-events", 0),
                0, 0, 0L, 0, 0);
        when(result.getRecordMetadata()).thenReturn(md);
        when(kafka.send(any(String.class), any(String.class), any(OrderEvent.class)))
                .thenReturn(CompletableFuture.completedFuture(result));
        service = new OrderService(kafka);
    }

    @Test
    void placeOrder_publishesPlacedEventKeyedByOrderId() {
        OrderEvent ev = service.placeOrder("o-1");

        assertThat(ev.getOrderId()).isEqualTo("o-1");
        assertThat(ev.getState()).isEqualTo(OrderState.PLACED);
        assertThat(ev.getPreviousState()).isNull();

        ArgumentCaptor<OrderEvent> captor = ArgumentCaptor.forClass(OrderEvent.class);
        verify(kafka).send(eq("order-events"), eq("o-1"), captor.capture());
        assertThat(captor.getValue().getState()).isEqualTo(OrderState.PLACED);
    }

    @Test
    void advance_walksThroughEntireLifecycle() {
        OrderState[] expected = {
                OrderState.ACCEPTED,
                OrderState.PREPARING,
                OrderState.OUT_FOR_DELIVERY,
                OrderState.DELIVERED,
        };

        OrderState current = OrderState.PLACED;
        for (OrderState next : expected) {
            OrderEvent ev = service.advance("o-2", current);
            assertThat(ev.getState()).isEqualTo(next);
            assertThat(ev.getPreviousState()).isEqualTo(current);
            current = next;
        }
    }

    @Test
    void advance_invalidTransitionFromDelivered_throws() {
        assertThatThrownBy(() -> service.advance("o-3", OrderState.DELIVERED))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("DELIVERED");
    }
}

package com.fooddelivery.producer;

import com.fooddelivery.OrderEvent;
import com.fooddelivery.OrderState;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.clients.producer.RecordMetadata;
import org.apache.kafka.common.TopicPartition;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.core.ProducerFactory;
import org.springframework.kafka.support.SendResult;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;

/**
 * Unit tests for {@link OrderService}. Generated by the agentic-AI demo.
 *
 * Note: we don't try to mock {@link KafkaTemplate} directly (Mockito's
 * inline mock maker cannot subclass it under recent JDKs). Instead we use
 * a tiny hand-rolled subclass that records every send() call.
 */
class OrderServiceTest {

    /** Records every send() and returns a successful SendResult. */
    static final class RecordingKafkaTemplate extends KafkaTemplate<String, OrderEvent> {
        final List<ProducerRecord<String, OrderEvent>> sent = new ArrayList<>();

        @SuppressWarnings("unchecked")
        RecordingKafkaTemplate() {
            super((ProducerFactory<String, OrderEvent>) mock(ProducerFactory.class));
        }

        @Override
        public CompletableFuture<SendResult<String, OrderEvent>> send(
                String topic, String key, OrderEvent value) {
            ProducerRecord<String, OrderEvent> rec = new ProducerRecord<>(topic, key, value);
            sent.add(rec);
            RecordMetadata md = new RecordMetadata(
                    new TopicPartition(topic, 0), 0, 0, 0L, 0, 0);
            SendResult<String, OrderEvent> result = new SendResult<>(rec, md);
            return CompletableFuture.completedFuture(result);
        }
    }

    private RecordingKafkaTemplate kafka;
    private OrderService service;

    @BeforeEach
    void setUp() {
        kafka = new RecordingKafkaTemplate();
        service = new OrderService(kafka);
    }

    @Test
    void placeOrder_publishesPlacedEventKeyedByOrderId() {
        OrderEvent ev = service.placeOrder("o-1");

        assertThat(ev.getOrderId()).isEqualTo("o-1");
        assertThat(ev.getState()).isEqualTo(OrderState.PLACED);
        assertThat(ev.getPreviousState()).isNull();

        assertThat(kafka.sent).hasSize(1);
        ProducerRecord<String, OrderEvent> rec = kafka.sent.get(0);
        assertThat(rec.topic()).isEqualTo("order-events");
        assertThat(rec.key()).isEqualTo("o-1");
        assertThat(rec.value().getState()).isEqualTo(OrderState.PLACED);
    }

    @Test
    void advance_walksThroughEntireLifecycle() {
        OrderState[] expected = {
                OrderState.ACCEPTED,
                OrderState.PREPARING,
                OrderState.OUT_FOR_DELIVERY,
                OrderState.DELIVERED,
        };

        OrderState current = OrderState.PLACED;
        for (OrderState next : expected) {
            OrderEvent ev = service.advance("o-2", current);
            assertThat(ev.getState()).isEqualTo(next);
            assertThat(ev.getPreviousState()).isEqualTo(current);
            current = next;
        }
        assertThat(kafka.sent).hasSize(4);
        assertThat(kafka.sent).allMatch(r -> r.key().equals("o-2"));
    }

    @Test
    void advance_invalidTransitionFromDelivered_throws() {
        assertThatThrownBy(() -> service.advance("o-3", OrderState.DELIVERED))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("DELIVERED");
        assertThat(kafka.sent).isEmpty();
    }
}

"""Typer-based CLI entry point: `food-delivery-demo`.""" from __future__ import annotations
import shutil from pathlib import Path from typing import Optional
import typer from rich.console import Console
from . import git_ops from .config import DEFAULT_TARGET_REPO, load_settings from .workflow import run_demo
app = typer.Typer( add_completion=False, help="Reusable agentic-AI demo: six agents generate JUnit tests for a Spring Boot Kafka service.", no_args_is_help=True, ) console = Console()
def _settings(target, provider, speed, max_loops, coverage_gate, branch, base_branch, open_pr, headless): return load_settings( target_repo=target, provider=provider, speed=speed, max_loops=max_loops, coverage_threshold=coverage_gate, branch_name=branch, base_branch=base_branch, open_pr=open_pr, headless=headless, )
@app.command() def run( target_repo: Path = typer.Option(DEFAULT_TARGET_REPO, "--target-repo", "-r", help="Path to the Maven repo to operate on."), provider: str = typer.Option("mock", "--provider", "-p", help="LLM provider: mock | openai | anthropic"), speed: str = typer.Option("normal", "--speed", "-s", help="Pacing: instant | fast | normal | slow"), max_loops: int = typer.Option(3, "--max-loops", help="Maximum quality-gate fix iterations."), coverage_gate: float = typer.Option(80.0, "--coverage-gate", help="Required coverage percentage."), branch: str = typer.Option("feat/agentic-ai-tests", "--branch"), base_branch: str = typer.Option("main", "--base-branch"), open_pr: bool = typer.Option(False, "--open-pr", help="Push branch and open a GitHub PR via gh CLI."), headless: bool = typer.Option(False, "--headless", help="Disable live UI (useful for CI / log capture)."), ): """Run the full agentic-AI workflow against a target repo.""" settings = _settings(target_repo, provider, speed, max_loops, coverage_gate, branch, base_branch, open_pr, headless) run_demo(settings)
@app.command() def reset( target_repo: Path = typer.Option(DEFAULT_TARGET_REPO, "--target-repo", "-r"), branch: str = typer.Option("feat/agentic-ai-tests", "--branch"), base_branch: str = typer.Option("main", "--base-branch"), ): """Reset the target repo to a clean baseline so the demo can be re-run.""" if not target_repo.exists(): console.print(f"[red]target repo not found: {target_repo}[/]") raise typer.Exit(1)
console.print(f"[cyan]Resetting {target_repo} → {base_branch}[/]")
# 1) check out base branch (force) try: git_ops._run(["git", "checkout", base_branch], target_repo) except RuntimeError: # uncommitted changes? hard reset and try again git_ops._run(["git", "reset", "--hard"], target_repo, check=False) git_ops._run(["git", "checkout", base_branch], target_repo)
# 2) delete generated branch git_ops.delete_branch(target_repo, branch) console.print(f" [green]✓ deleted branch {branch}[/]")
# 3) wipe generated tests test_dir = target_repo / "src" / "test" if test_dir.exists(): shutil.rmtree(test_dir) console.print(f" [green]✓ removed {test_dir}[/]") else: console.print(" [dim]· no src/test/ to remove[/]")
console.print("[bold green]Reset complete.[/]")
@app.command() def status( target_repo: Path = typer.Option(DEFAULT_TARGET_REPO, "--target-repo", "-r"), ): """Show what state the target repo is in.""" if not target_repo.exists(): console.print(f"[red]target repo not found: {target_repo}[/]") raise typer.Exit(1) console.print(f"[bold]Repo:[/] {target_repo}") console.print(f"[bold]Branch:[/] {git_ops.current_branch(target_repo)}") test_dir = target_repo / "src" / "test" n_tests = len(list(test_dir.rglob("*.java"))) if test_dir.exists() else 0 console.print(f"[bold]Generated tests:[/] {n_tests}")
@app.command() def doctor(): """Quick environment check.""" import importlib.util as iu rows = [ ("python-pptx (optional)", iu.find_spec("pptx") is not None), ("openai (optional)", iu.find_spec("openai") is not None), ("anthropic (optional)", iu.find_spec("anthropic") is not None), ("git", bool(shutil.which("git"))), ("mvn", bool(shutil.which("mvn"))), ("gh", bool(shutil.which("gh"))), ] for name, ok in rows: mark = "[green]✓[/]" if ok else "[yellow]·[/]" console.print(f" {mark} {name}")
def main(): # for `python -m agentic_demo` app()
if __name__ == "__main__": main()

