"""LLM client abstraction with mock / openai / anthropic providers."""
from __future__ import annotations

import os
from abc import ABC, abstractmethod
from dataclasses import dataclass


class LLMClient(ABC):
    name: str

    @abstractmethod
    async def complete(self, system: str, user: str, *, temperature: float = 0.2) -> str: ...


# ---------------------------------------------------------------------------
# Mock provider — deterministic, offline. Returns canned narrative responses
# keyed by simple substring detection in the prompt. Great for stage demos.
# ---------------------------------------------------------------------------
class MockLLM(LLMClient):
    name = "mock"

    _CANNED = {
        "test plan": (
            "Plan:\n"
            "  1. OrderServiceTest – verify each transition publishes the right event.\n"
            "  2. RestaurantServiceTest – verify only PLACED/ACCEPTED/PREPARING are handled.\n"
            "  3. DeliveryServiceTest – verify PREPARING/OUT_FOR_DELIVERY/DELIVERED handled.\n"
            "  4. NotificationServiceTest – verify a message is produced for every state.\n"
            "  5. OrderLifecycleIntegrationTest – embedded Kafka, full PLACED→DELIVERED."
        ),
        "review": (
            "LGTM overall. Two suggestions:\n"
            "  - assert partition is stable for the same orderId.\n"
            "  - cover invalid transition (DELIVERED → PREPARING)."
        ),
        "fix": "Adding test for invalid state transition + asserting partition stability.",
    }

    async def complete(self, system: str, user: str, *, temperature: float = 0.2) -> str:
        low = (system + "\n" + user).lower()
        for k, v in self._CANNED.items():
            if k in low:
                return v
        return "OK."


class OpenAILLM(LLMClient):
    name = "openai"

    def __init__(self, model: str = "gpt-4o-mini"):
        from openai import AsyncOpenAI  # type: ignore
        self._client = AsyncOpenAI()
        self.model = model

    async def complete(self, system: str, user: str, *, temperature: float = 0.2) -> str:
        resp = await self._client.chat.completions.create(
            model=self.model,
            temperature=temperature,
            messages=[
                {"role": "system", "content": system},
                {"role": "user",   "content": user},
            ],
        )
        return resp.choices[0].message.content or ""


class AnthropicLLM(LLMClient):
    name = "anthropic"

    def __init__(self, model: str = "claude-3-5-haiku-latest"):
        import anthropic  # type: ignore
        self._client = anthropic.AsyncAnthropic()
        self.model = model

    async def complete(self, system: str, user: str, *, temperature: float = 0.2) -> str:
        msg = await self._client.messages.create(
            model=self.model,
            max_tokens=1024,
            temperature=temperature,
            system=system,
            messages=[{"role": "user", "content": user}],
        )
        # anthropic returns a list of content blocks
        return "".join(block.text for block in msg.content if hasattr(block, "text"))


def make_llm(provider: str) -> LLMClient:
    provider = (provider or "mock").lower()
    if provider == "openai":
        if not os.environ.get("OPENAI_API_KEY"):
            raise RuntimeError("OPENAI_API_KEY is not set")
        return OpenAILLM()
    if provider == "anthropic":
        if not os.environ.get("ANTHROPIC_API_KEY"):
            raise RuntimeError("ANTHROPIC_API_KEY is not set")
        return AnthropicLLM()
    return MockLLM()

"""Pretty terminal UI for the agentic demo (rich-based).""" from __future__ import annotations
import asyncio from contextlib import contextmanager from dataclasses import dataclass from typing import Iterable
from rich.console import Console, Group from rich.live import Live from rich.panel import Panel from rich.progress import ( BarColumn, Progress, SpinnerColumn, TextColumn, TimeElapsedColumn, ) from rich.rule import Rule from rich.table import Table from rich.text import Text
# --------------------------------------------------------------------------- # Visual identity per agent — color + emoji prefix # --------------------------------------------------------------------------- AGENT_STYLES: dict[str, tuple[str, str]] = { "orchestrator": ("bold magenta", ""), "analyzer": ("bold cyan", ""), "writer": ("bold green", "✍️ "), "writer-producer": ("green", "✍️ "), "writer-consumer": ("green", "✍️ "), "writer-integration": ("green", "✍️ "), "coverage": ("bold yellow", ""), "sonar": ("bold red", "️ "), "reviewer": ("bold blue", ""), "devops": ("bold white", ""), }
console = Console(highlight=False)
def banner() -> None: console.print() console.print( Panel.fit( Text.from_markup( "[bold magenta]Agentic AI Demo[/] • " "[cyan]Six agents, one pipeline[/] • " "[green]Hands-off JUnit generation[/]" ), border_style="magenta", padding=(1, 4), ), justify="center", ) console.print()
def section(title: str) -> None: console.print() console.print(Rule(f"[bold]{title}[/]", style="magenta"))
def agent_say(agent: str, message: str, *, level: str = "info") -> None: style, emoji = AGENT_STYLES.get(agent, ("white", "•")) color = {"info": "white", "success": "green", "warn": "yellow", "error": "red"}[level] console.print( f" [{style}]{emoji} {agent.upper():<22}[/]" f" [dim]│[/] [{color}]{message}[/]" )
def kv_panel(title: str, items: Iterable[tuple[str, str]], *, color: str = "cyan") -> None: table = Table.grid(padding=(0, 2)) table.add_column(style="bold") table.add_column() for k, v in items: table.add_row(k, v) console.print(Panel(table, title=title, border_style=color, padding=(1, 2)))
@contextmanager def working(agent: str, label: str): """A spinner that lives for the duration of a 'with' block.""" style, emoji = AGENT_STYLES.get(agent, ("white", "•")) progress = Progress( SpinnerColumn(style=style), TextColumn(f"[{style}]{emoji} {agent.upper():<22}[/] [dim]│[/] " + label), TimeElapsedColumn(), transient=True, console=console, ) progress.start() task = progress.add_task("", total=None) try: yield finally: progress.update(task, completed=1) progress.stop()
@dataclass class WriterRow: name: str status: str = "queued" # queued | running | done | failed detail: str = ""
class ParallelWritersView: """A live, multi-row view for the parallel writer fan-out.""" def __init__(self, rows: list[WriterRow]): self.rows = rows
def render(self) -> Panel: table = Table.grid(padding=(0, 2)) table.add_column(width=24) table.add_column(width=12) table.add_column() for r in self.rows: style, emoji = AGENT_STYLES.get(r.name, ("white", "•")) status_color = { "queued": "dim", "running": "yellow", "done": "green", "failed": "red", }[r.status] table.add_row( f"[{style}]{emoji} {r.name:<22}[/]", f"[{status_color}]{r.status:<8}[/]", r.detail, ) return Panel( table, title="⚡ PARALLEL WRITERS", border_style="green", padding=(1, 2), )
@contextmanager def live(self): with Live(self.render(), refresh_per_second=8, console=console) as live: self._live = live try: yield self finally: self._live = None
def update(self, name: str, *, status: str | None = None, detail: str | None = None): for r in self.rows: if r.name == name: if status is not None: r.status = status if detail is not None: r.detail = detail break if getattr(self, "_live", None): self._live.update(self.render())
def merged_summary(state) -> None: style = "green" table = Table.grid(padding=(0, 2)) table.add_column(style="bold") table.add_column() table.add_row("Branch", state.branch or "-") table.add_row("Commits", str(len(state.commits))) table.add_row("Tests written", str(len(state.tests))) table.add_row("Coverage", f"{state.coverage.overall_pct:.1f}%" if state.coverage else "-") table.add_row("Sonar", "PASS" if state.sonar and state.sonar.passed else "FAIL") table.add_row("Review", f"{len(state.review)} comment(s)") table.add_row("Iterations", str(state.iterations)) table.add_row("PR", state.pr_url or "(local only — pass --open-pr to publish)") console.print() console.print(Panel(table, title="✅ PR MERGED", border_style=style, padding=(1, 4))) console.print()
async def beat(seconds: float) -> None: """Async sleep helper that respects very small / zero values.""" if seconds > 0: await asyncio.sleep(seconds)

