def _score_color(score: float) -> str: if score >= 0.85: return "bright_green" if score >= 0.65: return "yellow" return "red"
def _bar(score: float, width: int = 18) -> str: filled = max(0, min(width, int(round(score * width)))) return "█" * filled + "·" * (width - filled)
def evals_panel(results, *, title: str = " EVALUATIONS") -> None: """Render an evaluation results table grouped by agent + overall.""" table = Table.grid(padding=(0, 2)) table.add_column(width=24, style="bold") table.add_column(width=22) table.add_column(width=8, justify="right") table.add_column()
overall = None for r in results: if r.name == "overall": overall = r continue color = _score_color(r.score) table.add_row( r.name, f"[{color}]{_bar(r.score)}[/]", f"[{color}]{r.score:.2f}[/]", f"[dim]{r.rationale}[/]", ) if overall is not None: color = _score_color(overall.score) table.add_row("", "", "", "") table.add_row( "[bold]OVERALL[/]", f"[bold {color}]{_bar(overall.score)}[/]", f"[bold {color}]{overall.score:.2f}[/]", f"[bold]{overall.rationale}[/]", )
console.print() console.print(Panel(table, title=title, border_style="magenta", padding=(1, 2)))
def trace_panel(*, backend: str, url: str | None, model: str | None) -> None: table = Table.grid(padding=(0, 2)) table.add_column(style="bold") table.add_column() table.add_row("Backend", backend) table.add_row("Model", model or "-") table.add_row("Trace", url or "-") console.print(Panel(table, title=" Observability", border_style="cyan", padding=(1, 2)))
